final class MpFaceMeshContext extends ffi.Opaque {}

final class MpFaceDetectorContext extends ffi.Opaque {}

enum MpPixelFormat {
  MP_PIXEL_FORMAT_RGBA(0),
  MP_PIXEL_FORMAT_BGRA(1);

  final int value;
  const MpPixelFormat(this.value);

  static MpPixelFormat fromValue(int value) => switch (value) {
    0 => MP_PIXEL_FORMAT_RGBA,
    1 => MP_PIXEL_FORMAT_BGRA,
    _ => throw ArgumentError("Unknown value for MpPixelFormat: $value"),
  };
}

enum MpDelegateType {
  MP_DELEGATE_CPU(0),
  MP_DELEGATE_XNNPACK(1);

  final int value;
  const MpDelegateType(this.value);

  static MpDelegateType fromValue(int value) => switch (value) {
    0 => MP_DELEGATE_CPU,
    1 => MP_DELEGATE_XNNPACK,
    _ => throw ArgumentError("Unknown value for MpDelegateType: $value"),
  };
}

final class MpImage extends ffi.Struct {
