}

final class MpLandmark extends ffi.Struct {
  @ffi.Float()
  external double x;

  @ffi.Float()
  external double y;

  @ffi.Float()
  external double z;
}

final class MpFaceMeshResult extends ffi.Struct {
  external ffi.Pointer<MpLandmark> landmarks;

  @ffi.Int32()
  external int landmarks_count;

  external MpNormalizedRect rect;

  @ffi.Float()
  external double score;

  @ffi.Int32()
  external int image_width;

  @ffi.Int32()
  external int image_height;
}

final class MpFaceMeshMultiResult extends ffi.Struct {
  /// One entry per input ROI, in input order. Entries whose face presence
  /// score fell below the threshold have landmarks_count == 0, matching
  /// mp_face_mesh_process.
  external ffi.Pointer<MpFaceMeshResult> results;

  @ffi.Int32()
  external int results_count;
}

final class MpFaceGeometryOptions extends ffi.Struct {
  /// Vertical field of view of the virtual camera in degrees.
  @ffi.Float()
  external double vertical_fov_degrees;

  /// Near and far clip planes of the virtual frustum in the same units as the
  /// output metric landmarks (centimeters).
  @ffi.Float()
  external double near_plane;

  @ffi.Float()
  external double far_plane;

  /// Non-zero when input normalized landmarks use a top-left image origin.
  /// This matches FaceMeshResult landmarks returned by this plugin.
  @ffi.Uint8()
  external int origin_top_left;
}

final class MpFaceGeometryResult extends ffi.Struct {
  /// Landmarks reprojected into centimeter-scale metric space.
  external ffi.Pointer<MpLandmark> metric_landmarks;

  @ffi.Int32()
  external int metric_landmarks_count;

  /// Row-major 4x4 similarity transform from canonical face space to camera
  /// space. Encodes rotation, translation, and uniform scale.
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Float> pose_transform_matrix;

  @ffi.Float()
  external double yaw_degrees;

  @ffi.Float()
  external double pitch_degrees;

  @ffi.Float()
  external double roll_degrees;

  /// Uniform scale factor from the Procrustes fit: ratio of the observed face
  /// size to the canonical model size in centimeters.
  @ffi.Float()
  external double scale;
}

final class MpFaceMeshCreateOptions extends ffi.Struct {
  external ffi.Pointer<ffi.Char> iris_model_path;

  @ffi.Int32()
  external int threads;

  @ffi.Float()
  external double min_detection_confidence;

  @ffi.Float()
  external double min_tracking_confidence;

  @ffi.Float()
  external double min_face_presence_confidence;

  @ffi.UnsignedInt()
  external int delegate;

  @ffi.Uint8()
  external int enable_roi_tracking;

  @ffi.Uint8()
  external int enable_iris;

  /// When non-zero, [model_path] points to the unified
  /// `face_landmark_with_attention` model, which refines lips, eyes, and irises
  /// in a single inference and outputs 478 landmarks directly. Requires a
  /// libtensorflowlite_c that registers the MediaPipe custom ops. When set, the
  /// separate iris pass ([enable_iris]/[iris_model_path]) is not used; iris is
  /// always included in the result.
  @ffi.Uint8()
  external int enable_attention_mesh;

  /// When non-zero, fail creation instead of falling back to CPU if the
  /// requested delegate is unavailable or cannot be created.
  @ffi.Uint8()
  external int disable_delegate_fallback;
}

